using System.Globalization;
using Saldo360.Application.Families;
using Saldo360.Application.Transactions;
using Saldo360.Domain.Common;
using Saldo360.Domain.Debts;

namespace Saldo360.Application.Debts;

public sealed class FinancialDebtService(IFamilyRepository families, IFinancialDebtRepository repository, IReferenceLookup references, TimeProvider time)
{
    public async Task<DebtResult> CreateAsync(Guid familyId, Guid userId, DebtInput input, CancellationToken ct)
    { if (!await Member(familyId,userId,ct)) return new(DebtAccess.NotFound,null,null); var (details,errors)=await Validate(familyId,input,ct); if(details is null)return new(DebtAccess.Invalid,null,errors); var entity=FinancialDebt.Create(familyId,details,time.GetUtcNow()); await repository.AddAsync(entity,ct); return new(DebtAccess.Allowed,await repository.GetAsync(familyId,entity.Id,ct),null); }
    public async Task<DebtDto?> GetAsync(Guid familyId,Guid id,Guid userId,CancellationToken ct)=>await Member(familyId,userId,ct)?await repository.GetAsync(familyId,id,ct):null;
    public async Task<(IReadOnlyList<DebtDto>? Items,bool NotFound)> ListAsync(Guid familyId,Guid userId,bool includeArchived,CancellationToken ct)=>!await Member(familyId,userId,ct)?(null,true):(await repository.ListAsync(familyId,includeArchived,ct),false);
    public async Task<DebtResult> UpdateAsync(Guid familyId,Guid id,Guid userId,DebtInput input,CancellationToken ct){if(!await Member(familyId,userId,ct))return new(DebtAccess.NotFound,null,null);var entity=await repository.FindAsync(familyId,id,ct);if(entity is null)return new(DebtAccess.NotFound,null,null);var (details,errors)=await Validate(familyId,input,ct);if(details is null)return new(DebtAccess.Invalid,null,errors);try{entity.Update(details,time.GetUtcNow());await repository.SaveAsync(ct);return new(DebtAccess.Allowed,await repository.GetAsync(familyId,id,ct),null);}catch(InvalidOperationException ex){return new(DebtAccess.Conflict,null,null,ex.Message);}}
    public async Task<DebtResult> ChangeAsync(Guid familyId,Guid id,Guid userId,string operation,CancellationToken ct){if(!await Member(familyId,userId,ct))return new(DebtAccess.NotFound,null,null);var entity=await repository.FindAsync(familyId,id,ct);if(entity is null)return new(DebtAccess.NotFound,null,null);try{var now=time.GetUtcNow();if(operation=="suspend")entity.Suspend(now);else if(operation=="resume")entity.Resume(now);else if(operation=="settle")entity.Settle(now);else entity.Archive(now);await repository.SaveAsync(ct);return new(DebtAccess.Allowed,await repository.GetAsync(familyId,id,ct),null);}catch(InvalidOperationException ex){return new(DebtAccess.Conflict,null,null,ex.Message);}}
    private async Task<(DebtDetails?,Dictionary<string,string[]>)> Validate(Guid familyId,DebtInput i,CancellationToken ct){var e=new Dictionary<string,string[]>();var name=i.Name?.Trim()??string.Empty;if(name.Length==0)e["name"]=["Informe o nome da dívida."];else if(name.Length>FinancialDebt.NameMaxLength)e["name"]=["O nome excede o limite."];var description=string.IsNullOrWhiteSpace(i.Description)?null:i.Description.Trim();if(description is{Length:>FinancialDebt.DescriptionMaxLength})e["description"]=["A descrição excede o limite."];if(!Enum.TryParse<DebtType>(i.DebtType,true,out var type))e["debtType"]=["Modalidade de dívida inválida."];var lender=string.IsNullOrWhiteSpace(i.LenderName)?null:i.LenderName.Trim();if(lender is{Length:>FinancialDebt.LenderNameMaxLength})e["lenderName"]=["O credor excede o limite."];var original=MoneyValue(i.OriginalPrincipal,"originalPrincipal",e,true);var principal=MoneyValue(i.OutstandingPrincipal,"outstandingPrincipal",e,false);var balance=MoneyValue(i.OutstandingBalance,"outstandingBalance",e,false);var installment=MoneyValue(i.InstallmentAmount,"installmentAmount",e,false);var rate=MoneyValue(i.InterestRate,"interestRate",e,false);if(i.ContractDate is null)e["contractDate"]=["Informe a data do contrato."];if(i.BalanceReferenceDate is not null&&balance is null)e["balanceReferenceDate"]=["Informe o saldo devedor para usar a data de referência."];if(i.InstallmentCount is<=0)e["installmentCount"]=["A quantidade de parcelas deve ser positiva."];if(i.PaidInstallmentCount is<0)e["paidInstallmentCount"]=["A quantidade paga não pode ser negativa."];if(i.PaidInstallmentCount is not null&&i.InstallmentCount is not null&&i.PaidInstallmentCount>i.InstallmentCount)e["paidInstallmentCount"]=["Parcelas pagas não podem superar o total contratado."];InterestRatePeriod? period=null;if(i.InterestRatePeriod is not null){if(!Enum.TryParse<InterestRatePeriod>(i.InterestRatePeriod,true,out var p))e["interestRatePeriod"]=["Período da taxa inválido."];else period=p;}AmortizationMethod? method=null;if(i.AmortizationMethod is not null){if(!Enum.TryParse<AmortizationMethod>(i.AmortizationMethod,true,out var m))e["amortizationMethod"]=["Método de amortização inválido."];else method=m;}if(i.ResponsibleAccountId is{ } account){var state=await references.GetAccountStateAsync(familyId,account,ct);if(state is null)e["responsibleAccountId"]=["A conta não pertence à família."];else if(!state.IsActive)e["responsibleAccountId"]=["A conta está inativa."];}if(e.Count>0||original is null||i.ContractDate is null)return(null,e);return(new DebtDetails(i.ResponsibleAccountId,name,description,type,lender,original.Value,principal,balance,i.BalanceReferenceDate,i.ContractDate.Value,i.FirstDueDate,i.InstallmentCount,i.PaidInstallmentCount,installment,rate,period,method),e);}
    private static decimal? MoneyValue(string? text,string key,IDictionary<string,string[]> e,bool required){if(string.IsNullOrWhiteSpace(text)){if(required)e[key]=["Informe o valor."];return null;}if(!decimal.TryParse(text,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var value)||value<0||Money.Validate(value,"O valor") is not null)e[key]=["Informe um decimal não negativo com até duas casas."];return value;}
    private async Task<bool> Member(Guid familyId,Guid userId,CancellationToken ct)=>await families.GetMemberRoleAsync(familyId,userId,ct) is not null;
}
